import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import AuthLayout from "../../components/AuthLayout";
import { canSubmitAccountForm } from "../../utils/accountValidation";
import { inputClass, AlertError, PrimaryButton, PageTitle } from "../../components/ui";
import { getPortal } from "../../theme/portal";
import { saveEmailVerificationSession } from "../../services/emailVerificationApi";
import { register as apiRegister } from "../../services/accountApi";
import { parseApiError } from "../../services/auth";

const leftContent = (
  <div>
    <p className="text-[10px] tracking-[0.2em] text-white/60 uppercase mb-2">BUSINESS</p>
    <h2 className="font-serif text-3xl font-normal text-white leading-snug mb-6 italic">
      Acquire elite talent.<br />Scale your enterprise.
    </h2>
    <p className="text-sm text-white/70 leading-relaxed max-w-sm font-light">
      Build a verified presence to hire Algerian professionals, post jobs, and contract specialists directly.
    </p>
  </div>
);

export default function RegisterPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [agreedToTerms, setAgreedToTerms] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const canContinue = canSubmitAccountForm({
    email,
    password,
    confirmPassword,
    agreedToTerms,
  });

  const handleContinue = async () => {
    if (!canContinue || loading) return;
    const trimmed = email.trim();
    setLoading(true);
    setError("");
    try {
      await apiRegister({
        email: trimmed,
        password,
        password_confirm: confirmPassword,
        role: "enterprise",
      });
      const expiresAt = saveEmailVerificationSession("business", trimmed);
      navigate("/verify-email", { state: { email: trimmed, expiresAt } });
    } catch (err) {
      setError(parseApiError(err, "Unable to create your account. Please try again."));
    } finally {
      setLoading(false);
    }
  };

  return (
    <AuthLayout leftContent={leftContent} leftBg="bg-red">
      <PageTitle title="Create your account" subtitle="Business credentials for Linkio." />

      {/* Sleek Floating Switcher Cards (Matching Landing Page Cards) */}
      <div className="grid grid-cols-2 gap-4 mb-8 w-full select-none">
        {/* Professional Switch Card */}
        <button
          type="button"
          onClick={() => navigate("/professional/onboarding/account")}
          className="bg-white border border-gray-150 rounded-2xl p-4 flex items-center justify-center cursor-pointer transition-all duration-300 text-gray-400 hover:border-navy hover:text-navy hover:shadow-[0_8px_20px_rgba(27,58,92,0.08)] hover:scale-[1.02] active:scale-[0.98]"
        >
          <span className="text-xs font-semibold tracking-wide">Professional</span>
        </button>

        {/* Business Switch Card */}
        <button
          type="button"
          className="bg-red/[0.02] border border-red rounded-2xl p-4 flex items-center justify-center cursor-default transition-all duration-300 text-red font-semibold shadow-sm"
        >
          <span className="text-xs font-semibold tracking-wide">Business</span>
        </button>
      </div>

      <label className="block text-sm font-medium text-navy-deep mb-1">Business Email</label>
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className={`${inputClass} mb-4`}
        placeholder="you@company.dz"
      />

      <label className="block text-sm font-medium text-navy-deep mb-1">Password</label>
      <input
        type="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className={`${inputClass} mb-1`}
        placeholder="Enter a password"
      />
      <p className="text-xs text-gray-500 mb-4">At least 8 characters</p>

      <label className="block text-sm font-medium text-navy-deep mb-1">Confirm Password</label>
      <input
        type="password"
        value={confirmPassword}
        onChange={(e) => setConfirmPassword(e.target.value)}
        className={`${inputClass} mb-5`}
        placeholder="Repeat your password"
      />

      <AlertError>{error}</AlertError>

      <label className="flex items-center gap-2 text-sm text-gray-500 mb-5 cursor-pointer">
        <input
          type="checkbox"
          checked={agreedToTerms}
          onChange={(e) => setAgreedToTerms(e.target.checked)}
          className={`w-4 h-4 ${getPortal("business").checkbox}`}
        />
        <span>
          I agree to the <span className="text-red underline">Terms of Service</span> and{" "}
          <span className="text-red underline">Privacy Policy</span>
        </span>
      </label>

      <PrimaryButton portal="business" disabled={!canContinue} loading={loading} onClick={handleContinue}>
        Continue →
      </PrimaryButton>

      <p className="text-sm text-gray-500 text-center mt-4">
        Already have an account?{" "}
        <Link to="/sign-in" className="text-red font-semibold hover:underline">
          Sign in
        </Link>
      </p>
    </AuthLayout>
  );
}
